const body = $input.first().json.body;
const valid = body && typeof body === 'object' && !Array.isArray(body)
  && typeof body.request_id === 'string' && body.request_id.length >= 1 && body.request_id.length <= 64
  && typeof body.query === 'string' && body.query.trim().length > 0
  && typeof body.type === 'string' && body.type.trim().length > 0
  && Array.isArray(body.access_levels) && body.access_levels.length === 1 && body.access_levels[0] === 'all'
  && body.top_k === 3;
return [{json:{valid:!!valid, request:valid ? {request_id:body.request_id,query:body.query,type:body.type,access_levels:['all'],top_k:3} : null}}];

const x=$input.first().json;
const failure={status:503,body:{ok:false,evidence:[],reason:'search_unavailable'}};
if (x.error || ![200,503].includes(x.statusCode)) return [{json:failure}];
const b=x.body;
if (!b || typeof b!=='object' || Array.isArray(b)) return [{json:failure}];
if (x.statusCode===503) return [{json:failure}];
const rows=b.evidence;
if (b.ok!==true || !Array.isArray(rows) || rows.length>3 ||
    !rows.every(r=>r && typeof r.doc==='string' && r.doc.trim() && typeof r.section==='string' && r.section.trim() && typeof r.text==='string' && r.text.trim() && typeof r.score==='number' && Number.isFinite(r.score)) ||
    b.reason!==(rows.length ? null : 'no_evidence')) return [{json:failure}];
return [{json:{status:200,body:{ok:true,evidence:rows.map(r=>({doc:r.doc,section:r.section,text:r.text,score:r.score})),reason:b.reason}}}];
